/* codex-compare-direct-nightmode-end *//* codex-compare-nightmode-end */
/* Wrapper */
.ua-compare-wrap{
	width:100%;
	margin:24px 0 32px;
	background:var(--ua-compare-bg);
	border:1px solid var(--ua-compare-card-border);
	border-radius:var(--ua-compare-radius);
	box-shadow:var(--ua-compare-shadow);
	overflow:hidden;
}

/* Table */
.ua-compare-table{
	width:100%;
	border-collapse:separate;
	border-spacing:0;
	table-layout:fixed;
	margin:0;
	color:var(--ua-compare-text);
}

.ua-compare-table thead th{
	background:var(--ua-compare-head-bg);
	color:var(--ua-compare-text);
	font-weight:700;
	font-size:16px;
	line-height:1.25;
	padding:var(--ua-compare-cell-pad-y) var(--ua-compare-cell-pad-x);
	text-align:left;
	border:0;
}

.ua-compare-table tbody td{
	padding:var(--ua-compare-cell-pad-y) var(--ua-compare-cell-pad-x);
	vertical-align:top;
	font-size:16px;
	line-height:1.45;
	color:var(--ua-compare-text);
	border:0;
	word-break:normal;
	overflow-wrap:break-word;
}

.ua-compare-table tbody tr:nth-child(odd) td{
	background:var(--ua-compare-row-alt);
}

.ua-compare-table tbody tr:nth-child(even) td{
	background:var(--ua-compare-row-bg);
}

.ua-compare-table tbody tr td:first-child,
.ua-compare-table thead th:first-child{
	padding-left:20px;
}

.ua-compare-table tbody tr td:last-child,
.ua-compare-table thead th:last-child{
	padding-right:20px;
}

/* Column widths for desktop */
.ua-compare-table th.col-item,
.ua-compare-table td.col-item{
	width:20%;
}

.ua-compare-table th.col-best-for,
.ua-compare-table td.col-best-for{
	width:34%;
}

.ua-compare-table th.col-price,
.ua-compare-table td.col-price{
	width:18%;
}

.ua-compare-table th.col-features,
.ua-compare-table td.col-features{
	width:28%;
}

.ua-compare-table.ua-compare-table--no-price th.col-item,
.ua-compare-table.ua-compare-table--no-price td.col-item{
	width:22%;
}

.ua-compare-table.ua-compare-table--no-price th.col-best-for,
.ua-compare-table.ua-compare-table--no-price td.col-best-for{
	width:33%;
}

.ua-compare-table.ua-compare-table--no-price th.col-features,
.ua-compare-table.ua-compare-table--no-price td.col-features{
	width:45%;
}

/* Table links */
.ua-compare-table a.ua-compare-anchor{
	font-weight:700;
	text-decoration:none;
}

.ua-compare-table a.ua-compare-anchor:hover{
	text-decoration:underline;
}

/* Optional badge */
.ua-compare-badge{
	display:inline-block;
	margin-left:8px;
	padding:3px 8px;
	font-size:12px;
	line-height:1.2;
	font-weight:700;
	border-radius:999px;
	background:#eef2ff;
	color:#3730a3;
	vertical-align:middle;
}

/* Item heading */
.ua-item-heading{
	scroll-margin-top:var(--ua-compare-scroll-offset);
	margin-top:32px;
}

.ua-item-heading a{
	text-decoration:underline;
	text-underline-offset:2px;
}

/* Smooth scrolling */
html{
	scroll-behavior:smooth;
}

/* Mobile */
@media only screen and (max-width: 767px){
	.ua-compare-wrap{
		border-radius:12px;
		margin:20px 0 28px;
	}

	.ua-compare-table{
		table-layout:fixed;
	}

	.ua-compare-table thead th,
	.ua-compare-table tbody td{
		font-size:15px;
		line-height:1.4;
