.ua-yt-play:before{content:"";display:block;margin-left:4px;border-style:solid;border-width:14px 0 14px 22px;border-color:transparent transparent transparent #fff}
.ua-yt-title{position:absolute;left:12px;top:10px;right:12px;color:#fff;font:600 14px/1.3 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;text-shadow:0 2px 10px rgba(0,0,0,.6);opacity:.95}
.ua-yt-wrap iframe{position:absolute;inset:0;width:100%;height:100%}
