/* =================================================
   Variables
   ================================================= */

:root{
  --ua-link-color: #000000;
  --ua-link-underline-thickness: 1px;
  --ua-link-underline-offset: 2px;

  /* Body typography */
  --ua-body-font: 'Aparajita', sans-serif;
  --ua-body-color: rgba(0,0,0,.88);

  /* Author bio typography (secondary) */
  --ua-author-size: 15px;
  --ua-author-line: 1.45;
}

/* =================================================
   ARTICLE LINKS (content body)
   ================================================= */

/* Editorial links in article body */
#mvp-content-main a:not(.cta-button):not(.cta-button-primary):not([class*="button"]):not(.comparison-table-style a),
#mvp-content-main p a:not(.cta-button):not(.cta-button-primary):not([class*="button"]):not(.comparison-table-style a){
  color: var(--ua-link-color) !important;
  background: transparent !important;
  box-shadow: none !important;
  text-decoration: underline !important;
  text-decoration-thickness: var(--ua-link-underline-thickness);
  text-underline-offset: var(--ua-link-underline-offset);
}

#mvp-content-main a:not(.cta-button):not(.cta-button-primary):not([class*="button"]):hover,
#mvp-content-main p a:not(.cta-button):not(.cta-button-primary):not([class*="button"]):hover{
  color: var(--ua-link-color) !important;
  background: transparent !important;
  box-shadow: none !important;
}

#mvp-content-main a:not(.cta-button):not(.cta-button-primary):not([class*="button"]):visited,
#mvp-content-main p a:not(.cta-button):not(.cta-button-primary):not([class*="button"]):visited{
  color: var(--ua-link-color) !important;
}

/* =================================================
   AUTHOR BIO TYPOGRAPHY (secondary)
   ================================================= */

#mvp-author-box-text,
#mvp-author-box-text p{
  font-family: var(--ua-body-font) !important;
  font-size: var(--ua-author-size) !important;
  line-height: var(--ua-author-line) !important;
  color: var(--ua-body-color) !important;
  font-weight: 400 !important;
}

/* tighten paragraph spacing */
#mvp-author-box-text p{
  margin: 0 0 8px 0 !important;
}
#mvp-author-box-text p:last-child{
  margin-bottom: 0 !important;
}

/* small gap between author name line and bio */
#mvp-author-box-head{
  margin-bottom: 4px !important;
}

/* AUTHOR NAME LINE — no underline */
#mvp-author-box-head .mvp-author-box-name a,
#mvp-author-box-head .mvp-author-box-name a:hover,
#mvp-author-box-head .mvp-author-box-name a:visited{
  text-decoration: none !important;
}

/* ✅ CRITICAL FIX: AUTHOR BIO LINKS MUST NEVER GO PINK */
#mvp-author-box-text a,
#mvp-author-box-text a:hover,
#mvp-author-box-text a:visited{
  color: var(--ua-link-color) !important;
  background: transparent !important;
  box-shadow: none !important;
  text-decoration: underline !important;
  text-decoration-thickness: var(--ua-link-underline-thickness);
  text-underline-offset: var(--ua-link-underline-offset);
}

/* =================================================
   DISCLAIMER / TOP QUOTE — PLAIN, TIGHT, NO PINK
   ================================================= */

/* remove theme card look + tighten spacing */
.top__quote{
  background: transparent !important;
  border: 0 !important;
  border-left: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 !important;

  margin-top: 4px !important;     /* tight to byline */
  margin-bottom: 14px !important; /* normal before image */
}

/* disclaimer typography */
.top__quote p{
  font-family: var(--ua-body-font) !important;
  font-size: 15px !important;
  line-height: 1.4 !important;
  color: rgba(0,0,0,.72) !important;
  margin: 0 !important;
}

/* disclaimer links: black underline (never pink) */
.top__quote a,
.top__quote a:hover,
.top__quote a:visited{
  color: #000000 !important;
  background: transparent !important;
  box-shadow: none !important;
  text-decoration: underline !important;
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}

/* tighten spacing between author meta block and disclaimer (desktop gap killer) */
.mvp-author-info-wrap{
  margin-bottom: 6px !important;
}
#mvp-post-head{
  margin-bottom: 6px !important;
}

/* =================================================
   NightVision readiness (if you enable html.ua-nightvision)
   ================================================= */

html.ua-nightvision{
  --ua-body-color: rgba(234,234,234,.92);
}

html.ua-nightvision #mvp-content-main{
  color: rgba(234,234,234,.92) !important;
}

html.ua-nightvision #mvp-content-main a,
html.ua-nightvision #mvp-content-main a:hover,
html.ua-nightvision #mvp-content-main a:visited{
  color: rgba(245,245,245,.95) !important;
  text-decoration-color: rgba(245,245,245,.95) !important;
}

html.ua-nightvision #mvp-author-box-text,
html.ua-nightvision #mvp-author-box-text p{
  color: rgba(234,234,234,.92) !important;
}

html.ua-nightvision #mvp-author-box-text a,
html.ua-nightvision #mvp-author-box-text a:hover,
html.ua-nightvision #mvp-author-box-text a:visited{
  color: rgba(245,245,245,.95) !important;
  text-decoration-color: rgba(245,245,245,.95) !important;
}

html.ua-nightvision .top__quote p{
  color: rgba(234,234,234,.78) !important;
}

html.ua-nightvision .top__quote a,
html.ua-nightvision .top__quote a:hover,
html.ua-nightvision .top__quote a:visited{
  color: rgba(245,245,245,.95) !important;
  text-decoration-color: rgba(245,245,245,.95) !important;
}
