:root{
  --ua-rail-bg: #ffffff;
  --ua-rail-border: rgba(0,0,0,.10);
  --ua-rail-text: rgba(0,0,0,.88);
  --ua-rail-muted: rgba(0,0,0,.62);
  --ua-rail-width: 280px;
  --ua-rail-accent: #2f6fed;
  --ua-rail-top: 168px;
  --ua-rail-initial-offset: 12px;
}

@media (min-width: 1100px){

  #mvp-side-wrap.ua-rail-mounted{
    padding: 0 !important;
    transform: translateX(-18px);
    margin-top: var(--ua-rail-initial-offset) !important;
  }

  .ua-rail{
    position: sticky;
    top: var(--ua-rail-top);
    width: var(--ua-rail-width);
    z-index: 5;
  }

  .ua-rail__card{
    background: var(--ua-rail-bg);
    border: 1px solid var(--ua-rail-border);
    border-radius: 16px;
    padding: 14px 14px 12px 14px;
    box-shadow: 0 8px 30px rgba(0,0,0,.06);
    overflow: hidden;
  }

  .ua-rail__kicker{
    font: 700 11px/1.2 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: #111111 !important;
    margin: 0 0 10px 0;
  }

  .ua-rail__why{
    margin: 0 0 12px 0;
    font: 400 13px/1.45 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
    color: var(--ua-rail-muted);
  }

  .ua-rail__bullets{
    margin: 0 0 12px 0;
    padding: 0;
    list-style: none;
  }

  .ua-rail__bullets li{
    position: relative;
    margin: 0 0 12px 0;
    padding: 0 0 12px 18px;
    font: 400 13px/1.55 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
    color: var(--ua-rail-muted);
    border-bottom: 1px solid rgba(0,0,0,.08);
  }

  .ua-rail__bullets li:last-child{
    margin-bottom: 0;
    padding-bottom: 0;
    border-bottom: 0;
  }

  .ua-rail__bullets li::before{
    content: "";
    position: absolute;
    left: 0;
    top: 8px;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #111111;
  }

  .ua-rail__divider{
    height: 1px;
    background: rgba(0,0,0,.08);
    margin: 12px 0;
    border: 0;
  }

  .ua-rail__h{
    margin: 0 0 8px 0;
    font: 700 12.5px/1.2 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
    color: var(--ua-rail-text);
  }

  .ua-rail__stats{
    display: grid;
    gap: 8px;
    margin: 0;
  }

  .ua-rail__row{
    display:flex;
    justify-content: space-between;
    gap: 10px;
    font: 400 12.5px/1.25 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
    color: var(--ua-rail-muted);
  }

  .ua-rail__row b{
    font-weight: 650;
    color: var(--ua-rail-text);
  }

  .ua-rail__assets{ margin: 0; }

  .ua-rail__chips{
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin: 0 0 10px 0;
    padding: 0;
  }

  .ua-rail__chip,
  .ua-rail__chip:visited{
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 5px 9px;
    border: 1px solid rgba(0,0,0,.12);
    border-radius: 999px;
    background: rgba(0,0,0,.02);
    color: #111111 !important;
    text-decoration: none !important;
    font: 600 12px/1 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
    letter-spacing: .01em;
    white-space: nowrap;
  }

  .ua-rail__chip:hover,
  .ua-rail__chip:hover:visited{
    background: rgba(0,0,0,.03);
    border-color: rgba(0,0,0,.18);
    color: #111111 !important;
  }

  .ua-rail__toc{
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ua-rail__toc li{
    margin: 0 0 8px 0;
  }

  .ua-rail__toc a,
  .ua-rail__toc a:visited{
    display:block;
    position: relative;
    text-decoration: none;
    color: #111111 !important;
    font: 500 12.5px/1.25 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
    padding: 3px 6px 3px 18px;
    border-left: 0;
    border-radius: 0;
    background: transparent !important;
    transition: color .18s ease;
  }

  .ua-rail__toc a::before{
    content: "";
    position: absolute;
    left: 4px;
    top: 7px;
    width: 3px;
    height: calc(100% - 14px);
    min-height: 14px;
    border-radius: 999px;
    background: transparent;
    transition: background .18s ease;
  }

  .ua-rail__toc a:hover,
  .ua-rail__toc a:hover:visited{
    color: var(--ua-rail-accent) !important;
    background: transparent !important;
  }

  .ua-rail__toc a:hover::before{
    background: var(--ua-rail-accent);
  }

  .ua-rail__toc a.is-active,
  .ua-rail__toc a.is-active:visited{
    color: var(--ua-rail-accent) !important;
    background: transparent !important;
    font-weight: 650;
  }

  .ua-rail__toc a.is-active::before{
    background: var(--ua-rail-accent);
  }
}
