(function () {
  'use strict';

  function normalizeHost(host) {
    return String(host || '').toLowerCase().replace(/^www\./, '');
  }

  var ownHost = normalizeHost(window.location.hostname);

  function shouldUpgrade(link) {
    if (!link || !link.getAttribute) return false;
    var href = (link.getAttribute('href') || '').trim();
    if (!href || href.charAt(0) === '#') return false;

    try {
      var url = new URL(href, window.location.href);
      if (url.protocol !== 'http:' && url.protocol !== 'https:') return false;
      var sameHost = normalizeHost(url.hostname) === ownHost;
      return !sameHost || (sameHost && /^\/goto(?:\/|$)/i.test(url.pathname));
    } catch (error) {
      return false;
    }
  }

  function upgradeLink(link) {
    if (!shouldUpgrade(link)) return;
    link.setAttribute('target', '_blank');
    if (link.relList) {
      link.relList.add('noopener');
      link.relList.add('noreferrer');
    }
  }

  function upgradeTree(root) {
    if (!root) return;
    if (root.matches && root.matches('a[href]')) upgradeLink(root);
    if (root.querySelectorAll) root.querySelectorAll('a[href]').forEach(upgradeLink);
  }

  // Capture ensures a link injected immediately before a click is upgraded before
  // the browser performs its normal native navigation.
  document.addEventListener('click', function (event) {
    var target = event.target && event.target.closest ? event.target.closest('a[href]') : null;
    upgradeLink(target);
  }, true);

  function start() {
    upgradeTree(document);
    if (!document.body || !window.MutationObserver) return;
    new MutationObserver(function (mutations) {
      mutations.forEach(function (mutation) {
        mutation.addedNodes.forEach(upgradeTree);
      });
    }).observe(document.body, {childList: true, subtree: true});
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start, {once: true});
  } else {
    start();
  }
