/* ======================================================
   DESKTOP/TABLET: Grid layout underneath header
   ====================================================== */

@media (min-width: 480px){

  #mvp-related-posts ul.mvp-related-posts-list{
    display: grid !important;
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
    gap: 20px !important;
  }

  #mvp-related-posts ul.mvp-related-posts-list > a{
    display: block !important;
    float: none !important;
    width: auto !important;
    margin: 0 !important;
    padding: 0 !important;
    text-decoration: none !important;
  }

  #mvp-related-posts ul.mvp-related-posts-list > a li{
    float: none !important;
    width: 100% !important;
    height: auto !important;
    margin: 0 !important;
    padding: 0 !important;
    display: flex !important;
    flex-direction: column !important;
  }

  #mvp-related-posts .mvp-related-img{
    float: none !important;
    width: 100% !important;
    aspect-ratio: 16 / 9 !important;
    overflow: hidden !important;
    border-radius: 10px !important;
    margin: 0 0 12px 0 !important;
    background: transparent !important;
  }

  #mvp-related-posts .mvp-related-img img.mvp-reg-img{
    display: block !important;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
  }

  #mvp-related-posts img.mvp-mob-img{
    display: none !important;
  }

  #mvp-related-posts .mvp-related-text{
    float: none !important;
    width: 100% !important;
    margin: 0 !important;
    overflow: visible !important;
  }

  #mvp-related-posts .mvp-related-text p{
    margin: 0 !important;
    line-height: 1.15 !important;
    overflow: visible !important;
  }
}

/* ======================================================
   MOBILE: preserve original mobile logic
   ====================================================== */

@media (max-width: 479px){

  

  /* reset legacy layout */
  #mvp-related-posts ul.mvp-related-posts-list li{
    margin: 0 0 20px 0 !important;
    width: 100% !important;
    height: auto !important;
    padding: 0 0 20px 0 !important;
    border-bottom: 1px solid rgba(0,0,0,.10) !important;
  }

  #mvp-related-posts ul.mvp-related-posts-list > a:last-of-type li{
    border-bottom: none !important;
    padding-bottom: 0 !important;
  }

  /* force big image on */
  #mvp-related-posts img.mvp-reg-img{ display:block !important; }
  #mvp-related-posts img.mvp-mob-img{ display:none !important; }

  /* full 3:2 card */
  #mvp-related-posts .mvp-related-img{
    float: none !important;
    margin: 0 0 12px 0 !important;
    width: 100% !important;
    aspect-ratio: 3 / 2 !important;
    overflow: hidden !important;
    border-radius: 10px !important;
    background: transparent !important;
  }

  #mvp-related-posts .mvp-related-img img.mvp-reg-img{
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    display: block !important;
  }

  /* headline */
  #mvp-related-posts .mvp-related-text{
    float: none !important;
    width: 100% !important;
    margin: 0 !important;
  }

  #mvp-related-posts .mvp-related-text p{
    font-size: 18px !important;
    line-height: 1.25 !important;
    margin: 0 !important;
  }
}

 
