(function() {
	function getOffset() {
		var rootStyle = getComputedStyle(document.documentElement);
		var raw = rootStyle.getPropertyValue('--ua-compare-scroll-offset') || '120px';
		var parsed = parseInt(raw, 10);
		return isNaN(parsed) ? 120 : parsed;
	}

	function scrollToHashTarget(hash, updateHistory) {
		if (!hash || hash.charAt(0) !== '#') {
			return;
		}

		var target = document.querySelector(hash);
		if (!target) {
			return;
		}

		var offset = getOffset();
		var top = target.getBoundingClientRect().top + window.pageYOffset - offset;

		window.scrollTo({
			top: top,
			behavior: 'smooth'
		});

		if (updateHistory && history.pushState) {
			history.pushState(null, '', hash);
		}
	}

	document.addEventListener('click', function(event) {
		var link = event.target.closest('a[href^="#item-"]');
		if (!link) {
			return;
		}

		var href = link.getAttribute('href');
		if (!href) {
			return;
		}

		var target = document.querySelector(href);
		if (!target) {
			return;
		}

		event.preventDefault();
		scrollToHashTarget(href, true);
	});

	window.addEventListener('load', function() {
		if (window.location.hash && window.location.hash.indexOf('#item-') === 0) {
			setTimeout(function() {
				scrollToHashTarget(window.location.hash, false);
			}, 60);
		}
	});
})();
