(function(){
  function getYouTubeID(src){
    if(!src) return null;
    // Handles youtube.com/embed/ID, youtu.be/ID, and watch?v=ID
    var m = src.match(/(?:youtube\.com\/(?:embed\/|watch\?v=)|youtu\.be\/)([a-zA-Z0-9_-]{6,})/);
    return m ? m[1] : null;
  }

  function enhanceIframes(root){
    var iframes = root.querySelectorAll('iframe[src*="youtube.com"], iframe[src*="youtu.be"]');
    iframes.forEach(function(iframe){
      // Skip if already processed
      if(iframe.closest('.ua-yt-wrap')) return;

      var id = getYouTubeID(iframe.getAttribute('src'));
      if(!id) return;

      // Build placeholder
      var wrap = document.createElement('div');
      wrap.className = 'ua-yt-wrap';
      wrap.setAttribute('data-ytid', id);

      var thumb = document.createElement('img');
      thumb.loading = 'lazy';
      thumb.alt = '';
      // Try HQ thumbnail; if blocked, browser will fallback to black bg; still clickable
      thumb.src = 'https://i.ytimg.com/vi/' + id + '/hqdefault.jpg';

      var btn = document.createElement('button');
      btn.type = 'button';
      btn.setAttribute('aria-label', 'Play video');

      var play = document.createElement('div');
      play.className = 'ua-yt-play';
      btn.appendChild(play);

      // Optional title (if present in iframe title)
      var title = iframe.getAttribute('title');
      if(title){
        var t = document.createElement('div');
        t.className = 'ua-yt-title';
        t.textContent = title;
        wrap.appendChild(t);
      }

      wrap.appendChild(thumb);
      wrap.appendChild(btn);

      // On click, swap in iframe (autoplay)
      btn.addEventListener('click', function(){
        var newIframe = document.createElement('iframe');
        newIframe.width = '560';
        newIframe.height = '315';
        newIframe.loading = 'lazy';
        newIframe.allow = 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';
        newIframe.allowFullscreen = true;
        newIframe.referrerPolicy = 'strict-origin-when-cross-origin';
        newIframe.src = 'https://www.youtube.com/embed/' + id + '?autoplay=1&rel=0';

        wrap.innerHTML = '';
        wrap.appendChild(newIframe);
      });

      // Replace original iframe
      iframe.parentNode.replaceChild(wrap, iframe);
    });
  }

  document.addEventListener('DOMContentLoaded', function(){
    enhanceIframes(document);
  });
})();
